    get/list/envs（及经由 list 的 diff）共用的唯一一份读取校验规则：
    只接受严格的文本 true/false——不修剪空白、不转换大小写，yes、1
    等其他任何值都视为存储数据损坏，报 STORAGE_ERROR。纯校验，不修复
    记录、不输出原值。
    """
    if value == "true":
        return True
    if value == "false":
        return False
    raise FlagError("STORAGE_ERROR")

